update sys_menu_tl
menu_name = #{menuName}, menu_description = #{menuDescription}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where menu_id = #{menuId} and language = #{language}

update sys_menu_b
menu_sort = #{menuSort}, function_id = #{functionId}, parent_id = #{parentId}, child_id = #{childId}, menu_icon = #{menuIcon}, project_id=#{projectId}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where menu_id = #{menuId}

mapper.select:
select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
where mb.menu_id in

    #{menuId}

select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
where mb.menu_id = #{menuId}

select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}

    where mb.parent_id = #{parentId}


    where mb.parent_id is null

order by mb.menu_sort

select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
where mb.menu_code in

    #{code}

	select mb.menu_id,mb.menu_code,mb.function_id,mb.menu_icon,mb.parent_id,mb.child_id,mb.menu_sort,mtl.menu_name,mtl.menu_description,mb.project_id
	from sys_menu_b mb
    join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
    join sys_role_menu rm on rm.menu_id = mb.menu_id
	where rm.role_id = #{roleId}
	order by mb.menu_sort

select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
order by mb.menu_sort
LIMIT #{offset}, #{endset}

select mb.menu_id,mb.menu_code,mb.function_id,mb.menu_icon,mb.parent_id,mb.child_id,mb.menu_sort,mtl.menu_name,mtl.menu_description,mb.project_id
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
join sys_role_menu rm on rm.menu_id = mb.menu_id
where rm.role_id = #{roleId}
order by mb.menu_id
LIMIT #{offset}, #{endset}

select mb.*,mtl.menu_name,mtl.menu_description
from sys_menu_b mb
join sys_menu_tl mtl on mtl.menu_id = mb.menu_id and mtl.language = #{language}
where mb.parent_id is null

    and mb.project_id = #{projectId}

order by mb.menu_sort
